class Solution { public: vector<bool> checkArithmeticSubarrays(vector<int>& nums,vector<int>& l,vector<int>& r){vector<bool> answer;for(int query=0;query<(int)l.size();++query){vector<int> values(nums.begin()+l[query],nums.begin()+r[query]+1);sort(values.begin(),values.end());bool valid=true;int difference=values[1]-values[0];for(int i=2;i<(int)values.size();++i)if(values[i]-values[i-1]!=difference){valid=false;break;}answer.push_back(valid);}return answer;} };
